151	    /**
152	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
153	     * cannot form a valid E.164 number.
154	     *
155	     * <p>A leading '+' and country code are kept when present; otherwise country code
156	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
157	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
158	     * carry 8 to 15 digits after the '+'.
159	     */
160	    private String toE164(String telephone) {
161	        if (telephone == null) {
162	            return null;
163	        }
164	        boolean hasCountryCode = telephone.trim().startsWith("+");
165	        String digits = telephone.replaceAll("\\D", "");
166	        String e164;
167	        if (hasCountryCode) {
168	            e164 = digits;
169	        } else {
170	            if (digits.startsWith("0")) {
171	                digits = digits.substring(1);
172	            }
173	            e164 = "61" + digits;
174	        }
175	        if (e164.length() < 8 || e164.length() > 15) {
176	            return null;
177	        }
178	        return "+" + e164;
